function send_login_email( $email, $user, $token ) {
		$login_url = add_query_arg( 'token', rawurlencode( $token ), home_url( '/' . self::LOGIN_PATH ) );
		$is_new = ! $user;
		$name = '';
		if ( $user ) {
			$name = $user->first_name ? $user->first_name : $user->display_name;
		}

		$subject = $is_new ? 'Išsaugokite augintinio profilį — Petshop.lt' : 'Prisijungimas prie Petshop.lt';
		$title   = $is_new ? 'Išsaugokite augintinio profilį' : 'Prisijungimas prie Petshop.lt';
		$intro   = $is_new
			? 'Paspauskite mygtuką žemiau ir jūsų augintinio profilis bus išsaugotas — galėsite jį pasiekti bet kada.'
			: 'Gavome prašymą prisijungti prie jūsų paskyros. Paspauskite mygtuką žemiau:';
		$cta     = $is_new ? 'Išsaugoti profilį' : 'Prisijungti';

		$body  = '<html><body style="font-family:Arial,sans-serif;color:#333;max-width:560px;margin:0 auto;">';
		$body .= '<div style="padding:24px;">';
		$body .= '<h2 style="color:#2D5F3F;">' . esc_html( $title ) . '</h2>';
		$body .= '<p>Sveiki' . ( $name ? ', ' . esc_html( $name ) : '' ) . ',</p>';
		$body .= '<p>' . esc_html( $intro ) . '</p>';
		$body .= '<p style="margin:28px 0;"><a href="' . esc_url( $login_url ) . '" style="background:#2D5F3F;color:#fff;text-decoration:none;padding:14px 32px;border-radius:8px;font-weight:600;display:inline-block;">' . esc_html( $cta ) . '</a></p>';
		$body .= '<p style="color:#888;font-size:13px;">Nuoroda galioja 15 minučių ir gali būti panaudota vieną kartą.</p>';
		$body .= '<p style="color:#888;font-size:13px;">Jei šio prašymo nepateikėte — tiesiog ignoruokite šį laišką.</p>';
		$body .= '<hr style="border:none;border-top:1px solid #eee;margin:24px 0;">';
		$body .= '<p style="color:#aaa;font-size:12px;">Petshop.lt</p>';
		$body .= '</div></body></html>';

		$headers = array(
			'Content-Type: text/html; charset=UTF-8',
			'From: Petshop.lt <terra@petshop.lt>',
		);
		wp_mail( $email, $subject, $body, $headers );
	}

